begin;
create extension if not exists pgtap with schema extensions;
select plan(20);
insert into auth.users(id) select ('61000000-0000-0000-0000-00000000000'||n)::uuid from generate_series(1,3) n;
insert into auth.sessions(id,user_id,created_at,updated_at) select ('71000000-0000-0000-0000-00000000000'||n)::uuid,('61000000-0000-0000-0000-00000000000'||n)::uuid,now(),now() from generate_series(1,3) n;
insert into public.employees(id,employee_code,display_name,role) select ('81000000-0000-0000-0000-00000000000'||n)::uuid,'FAM'||n,'Synthetic','employee' from generate_series(1,3) n;
insert into private.employee_auth(employee_id,auth_user_id) select ('81000000-0000-0000-0000-00000000000'||n)::uuid,('61000000-0000-0000-0000-00000000000'||n)::uuid from generate_series(1,3) n;
insert into public.employee_permissions(employee_id,cases_read,cases_write) values ('81000000-0000-0000-0000-000000000001',true,false),('81000000-0000-0000-0000-000000000002',false,false),('81000000-0000-0000-0000-000000000003',true,true);
select has_column('public','families','contact_name','family has a primary contact name');
select has_column('public','families','contact_age','family contact age is stored');
select has_column('public','families','national_id','family contact ID is stored');
select has_column('public','families','phone_2','second contact phone is stored');
select has_column('public','families','phone_3','third contact phone is stored');
select has_column('public','families','notes','family note is stored');
select has_table('public','family_files','family attachments have separate metadata');
select ok((select not public from storage.buckets where id='case-files'),'shared attachment bucket remains private');
insert into public.families(id,name,contact_name,contact_age,national_id,phone,phone_2,phone_3,notes) values ('91000000-0000-0000-0000-000000000001','أسرة وهمية','مسؤول الأسرة',42,'29001011234567','01000000001','01000000002','01000000003','ملاحظة وهمية');
insert into public.cases(id,family_id,notes) values ('92000000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000001','حالة وهمية');
insert into storage.objects(bucket_id,name,owner_id) values ('case-files','91000000-0000-0000-0000-000000000001/91000000-0000-0000-0000-000000000002','61000000-0000-0000-0000-000000000001');
insert into public.family_files(id,family_id,storage_path,file_name,mime_type,size_bytes,uploaded_by) values ('91000000-0000-0000-0000-000000000002','91000000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000001/91000000-0000-0000-0000-000000000002','synthetic.png','image/png',5,'61000000-0000-0000-0000-000000000001');
select set_config('request.jwt.claims','{"sub":"61000000-0000-0000-0000-000000000001","session_id":"71000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.family_files),1,'staff with family read permission sees file metadata');
select is((select count(*)::int from storage.objects where bucket_id='case-files'),1,'staff with family read permission sees the private file object');
select is((select national_id from public.families where id='91000000-0000-0000-0000-000000000001'),'29001011234567','staff with family read permission sees contact details');
select ok(not exists(select 1 from public.assistant_search_cases('') f where f.families::text like '%29001011234567%'),'assistant retrieval does not return national IDs');
reset role;
select set_config('request.jwt.claims','{"sub":"61000000-0000-0000-0000-000000000003","session_id":"71000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.family_files),1,'case writers can also read family file metadata');
select lives_ok($$update public.families set contact_name='مسؤول معدل' where id='91000000-0000-0000-0000-000000000001'$$,'case writer can update family profile fields');
select is((select contact_name from public.families where id='91000000-0000-0000-0000-000000000001'),'مسؤول معدل','family profile update is saved');
select throws_ok($$insert into public.family_files(family_id,storage_path,file_name,mime_type,size_bytes,uploaded_by) values ('91000000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000001/91000000-0000-0000-0000-000000000003','fake.png','image/png',5,'61000000-0000-0000-0000-000000000003')$$,'42501',null,'writer cannot forge family file metadata');
reset role;
select set_config('request.jwt.claims','{"sub":"61000000-0000-0000-0000-000000000002","session_id":"71000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.family_files),0,'staff without family read permission sees no file metadata');
select is((select count(*)::int from storage.objects where bucket_id='case-files'),0,'staff without family read permission sees no file object');
reset role;
select throws_ok($$insert into public.families(name,national_id) values ('عينة','123')$$,'23514',null,'short national IDs are rejected');
select throws_ok($$insert into public.families(name,contact_age) values ('عينة',121)$$,'23514',null,'invalid ages are rejected');
select * from finish();
rollback;
